def maps_geocode(workspace_id, api_key_id, address, components=None, bounds=None, region=None, language=None, dedupe=None, **_extra):
    import json, os, datetime, re, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _validate_latlng(o, path):
        if not isinstance(o, dict):
            return f"{path} must be an object"
        if set(o.keys()) - {"lat", "lng"}:
            return f"{path} has unknown fields"
        if "lat" not in o or "lng" not in o:
            return f"{path}.lat and {path}.lng are required"
        if not isinstance(o["lat"], (int, float)) or not isinstance(o["lng"], (int, float)):
            return f"{path}.lat and {path}.lng must be numbers"
        if o["lat"] < -90 or o["lat"] > 90:
            return f"{path}.lat out of range"
        if o["lng"] < -180 or o["lng"] > 180:
            return f"{path}.lng out of range"
        return None

    def _validate():
        if not isinstance(workspace_id, str) or not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "Invalid workspace_id")
        if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
            return _err("VALIDATION_ERROR", "Invalid api_key_id")
        if not isinstance(address, str) or not address.strip():
            return _err("VALIDATION_ERROR", "address is required")
        if components is not None:
            if not isinstance(components, dict):
                return _err("VALIDATION_ERROR", "components must be an object")
            for k, v in components.items():
                if not isinstance(k, str) or not isinstance(v, str):
                    return _err("VALIDATION_ERROR", "components must be a string-to-string map")
        if bounds is not None:
            if not isinstance(bounds, dict):
                return _err("VALIDATION_ERROR", "bounds must be an object")
            if set(bounds.keys()) - {"southwest", "northeast"}:
                return _err("VALIDATION_ERROR", "bounds has unknown fields")
            if "southwest" not in bounds or "northeast" not in bounds:
                return _err("VALIDATION_ERROR", "bounds.southwest and bounds.northeast are required")
            e = _validate_latlng(bounds["southwest"], "bounds.southwest")
            if e: return _err("VALIDATION_ERROR", e)
            e = _validate_latlng(bounds["northeast"], "bounds.northeast")
            if e: return _err("VALIDATION_ERROR", e)
        if region is not None and (not isinstance(region, str) or not region.strip()):
            return _err("VALIDATION_ERROR", "region must be a non-empty string")
        if language is not None and (not isinstance(language, str) or not language.strip()):
            return _err("VALIDATION_ERROR", "language must be a non-empty string")
        if dedupe is not None and not isinstance(dedupe, bool):
            return _err("VALIDATION_ERROR", "dedupe must be boolean")
        return None

    def _period_bounds(now, kind):
        if kind == "day":
            start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            end = start + datetime.timedelta(days=1)
            return start, end
        if kind == "month":
            start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            if start.month == 12:
                end = start.replace(year=start.year + 1, month=1)
            else:
                end = start.replace(month=start.month + 1)
            return start, end
        return None, None

    def _find_workspace_api_key_and_connection(tool_name):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        conns = _load("provider_connections.json")

        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            return None, None, None, _err("NOT_FOUND", "Workspace not found")
        key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if not key:
            return None, None, None, _err("NOT_FOUND", "API key not found")
        if key.get("workspace_id") != ws.get("id"):
            return None, None, None, _err("UNAUTHORIZED", "API key does not belong to workspace")
        conn = next((c for c in conns if c.get("workspace_id") == ws.get("id") and c.get("provider") == "google_maps_platform"), None)
        if not conn:
            # No working combination for this request
            return ws, key, None, _err("UNAUTHORIZED", "No provider connection configured for workspace")
        allowed = conn.get("allowed_endpoints")
        if not isinstance(allowed, list) or tool_name not in allowed:
            return ws, key, conn, _err("UNAUTHORIZED", "Endpoint not allowed for this workspace")
        return ws, key, conn, None

    def _estimate(tool_name, normalized_input):
        # Simple deterministic model; non-negative and consistent with characteristics.
        billable_units = 1
        cost = 0.005
        if tool_name == "maps_geocode":
            cost = 0.005
        else:
            cost = 0.005
        if normalized_input and isinstance(normalized_input, dict):
            pass
        return int(billable_units), float(cost)

    def _cache_key(tool_name, normalized_input):
        b = json.dumps({"tool_name": tool_name, "normalized_input": normalized_input}, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _update_rollups(usage, ws_id, tool_name, now, add_req, add_units, add_cost):
        if add_req == 0 and add_units == 0 and add_cost == 0:
            return usage
        for period_type in ("day", "month"):
            ps, pe = _period_bounds(now, period_type)
            for tn in (tool_name, "*"):
                row = next((r for r in usage if r.get("workspace_id") == ws_id and r.get("period_type") == period_type and r.get("tool_name") == tn and r.get("period_start") == _iso(ps)), None)
                if not row:
                    row = {
                        "id": _gen_id("gmap_usage"),
                        "workspace_id": ws_id,
                        "period_start": _iso(ps),
                        "period_end": _iso(pe),
                        "period_type": period_type,
                        "tool_name": tn,
                        "request_count": 0,
                        "billable_units": 0,
                        "estimated_cost_usd": 0.0,
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    }
                    usage.append(row)
                row["request_count"] = int(row.get("request_count", 0)) + int(add_req)
                row["billable_units"] = int(row.get("billable_units", 0)) + int(add_units)
                row["estimated_cost_usd"] = float(row.get("estimated_cost_usd", 0.0)) + float(add_cost)
                row["updated_at"] = _iso(now)
        return usage

    def _projected_quota_exceeded(ws, now, add_req, add_cost):
        usage = _load("usage_rollups.json")
        day_start, _ = _period_bounds(now, "day")
        mon_start, _ = _period_bounds(now, "month")
        day_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "day" and r.get("tool_name") == "*" and r.get("period_start") == _iso(day_start)), None)
        mon_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "month" and r.get("tool_name") == "*" and r.get("period_start") == _iso(mon_start)), None)
        day_req = int((day_row or {}).get("request_count", 0)) + int(add_req)
        mon_req = int((mon_row or {}).get("request_count", 0)) + int(add_req)
        day_cost = float((day_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        mon_cost = float((mon_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        if day_req > int(ws.get("quota_daily_requests", 0)): return True
        if mon_req > int(ws.get("quota_monthly_requests", 0)): return True
        if day_cost > float(ws.get("quota_daily_cost_usd", 0.0)): return True
        if mon_cost > float(ws.get("quota_monthly_cost_usd", 0.0)): return True
        return False

    v = _validate()
    if v:
        return v

    tool_name = "maps_geocode"
    now = _now()

    ws, key, conn, auth_err = _find_workspace_api_key_and_connection(tool_name)
    if auth_err and auth_err["error"]["code"] in ("UNAUTHORIZED", "NOT_FOUND"):
        # Still must record request row (best-effort) only if we can associate workspace+key; if missing either, return error.
        if ws is None or key is None:
            return auth_err

    effective_region = region if region is not None else (ws.get("default_region") if ws else None)
    effective_language = language if language is not None else (ws.get("default_language") if ws else None)

    normalized_input = {
        "address": address.strip(),
        "components": components if components is not None else None,
        "bounds": bounds if bounds is not None else None,
        "region": effective_region,
        "language": effective_language,
    }
    ck = _cache_key(tool_name, normalized_input)
    billable_units, est_cost = _estimate(tool_name, normalized_input)

    # Prepare request row
    reqs = _load("maps_requests.json")
    usage = _load("usage_rollups.json")
    api_keys = _load("api_keys.json")

    req_id = _gen_id("gmap_req")
    base_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "provider_connection_id": conn.get("id") if conn else "",
        "tool_name": tool_name,
        "status": "queued",
        "input": {
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "address": address,
            "components": components,
            "bounds": bounds,
            "region": region,
            "language": language,
            "dedupe": dedupe,
        },
        "normalized_input": normalized_input,
        "cache_key": ck,
        "provider_http_method": "GET",
        "provider_url": "https://maps.googleapis.com/maps/api/geocode/json",
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": int(billable_units),
        "estimated_cost_usd": float(est_cost),
        "deduped_from_request_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Validate workspace/key/conn execution prerequisites
    final_status = None
    error_code = None
    error_message = None
    response = None
    provider_status_code = None

    if ws.get("status") != "active":
        final_status = "failed"
        error_code = "workspace_inactive"
        error_message = "Workspace is not active"
    else:
        # key status/expiry
        if key.get("status") != "active":
            final_status = "failed"
            error_code = "api_key_revoked_or_expired"
            error_message = "API key is not active"
        else:
            exp = _parse_dt(key.get("expires_at"))
            if exp is not None and exp <= now:
                final_status = "failed"
                error_code = "api_key_revoked_or_expired"
                error_message = "API key is expired"
    if final_status is None:
        if conn is None:
            final_status = "failed"
            error_code = "provider_connection_error"
            error_message = "No provider connection available"
        else:
            if conn.get("status") == "disabled":
                final_status = "failed"
                error_code = "provider_connection_disabled"
                error_message = "Provider connection disabled"
            elif conn.get("status") == "error":
                final_status = "failed"
                error_code = "provider_connection_error"
                error_message = "Provider connection error"
            elif conn.get("status") != "active":
                final_status = "failed"
                error_code = "provider_connection_error"
                error_message = "Provider connection not active"

    # Cache path (only if otherwise eligible)
    deduped_from = None
    if final_status is None and dedupe is True:
        hit = next((r for r in reqs if r.get("cache_key") == ck and r.get("tool_name") == tool_name and r.get("status") == "succeeded"), None)
        if hit:
            final_status = "succeeded"
            deduped_from = hit.get("id")
            response = hit.get("response")
            provider_status_code = hit.get("provider_status_code")

    # Quota enforcement (only if provider call would happen; still billed/rollup on terminal)
    if final_status is None:
        if _projected_quota_exceeded(ws, now, 1, est_cost):
            final_status = "failed"
            error_code = "quota_exceeded"
            error_message = "Quota exceeded"

    # "Execute provider call" offline: synthesize deterministic response when not failed
    if final_status is None:
        final_status = "succeeded"
        provider_status_code = 200
        response = {
            "status": "OK",
            "results": [
                {
                    "formatted_address": normalized_input["address"],
                    "geometry": {
                        "location": {"lat": 0.0, "lng": 0.0},
                        "location_type": "APPROXIMATE"
                    },
                    "place_id": "PLACE_ID_DEMO"
                }
            ],
        }

    # Transition: queued -> running -> terminal (respect lifecycle)
    # Record row
    base_row["provider_connection_id"] = conn.get("id") if conn else ""
    base_row["deduped_from_request_id"] = deduped_from
    base_row["status"] = "running"
    base_row["updated_at"] = _iso(now)
    reqs.append(base_row)

    # finalize
    end = _now()
    latency_ms = int(max(0, round((time.time() - _t0) * 1000)))
    base_row["status"] = final_status
    base_row["error_code"] = error_code
    base_row["error_message"] = error_message
    base_row["response"] = response
    base_row["provider_status_code"] = provider_status_code
    base_row["latency_ms"] = latency_ms
    base_row["updated_at"] = _iso(end)

    # Update last_used_at on key if we can
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = _iso(end)
            k["updated_at"] = _iso(end)
            break

    # Update rollups on terminal
    usage = _update_rollups(usage, workspace_id, tool_name, end, 1, billable_units, est_cost)

    _save("maps_requests.json", reqs)
    _save("usage_rollups.json", usage)
    _save("api_keys.json", api_keys)

    if final_status == "failed":
        return _err("QUOTA_EXCEEDED" if error_code == "quota_exceeded" else "UNAUTHORIZED" if error_code in ("workspace_inactive", "api_key_revoked_or_expired") else "CONFLICT",
                    "Request failed",
                    request_id=req_id,
                    error_code=error_code,
                    error_message=error_message)

    return {
        "request": base_row,
        "response": response,
        "deduped": bool(deduped_from),
    }

def maps_reverse_geocode(workspace_id, api_key_id, latlng, result_type=None, location_type=None, language=None, dedupe=None, **_extra):
    import json, os, datetime, re, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _validate_latlng(o, path):
        if not isinstance(o, dict):
            return f"{path} must be an object"
        if set(o.keys()) - {"lat", "lng"}:
            return f"{path} has unknown fields"
        if "lat" not in o or "lng" not in o:
            return f"{path}.lat and {path}.lng are required"
        if not isinstance(o["lat"], (int, float)) or not isinstance(o["lng"], (int, float)):
            return f"{path}.lat and {path}.lng must be numbers"
        if o["lat"] < -90 or o["lat"] > 90:
            return f"{path}.lat out of range"
        if o["lng"] < -180 or o["lng"] > 180:
            return f"{path}.lng out of range"
        return None

    def _validate():
        if not isinstance(workspace_id, str) or not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "Invalid workspace_id")
        if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
            return _err("VALIDATION_ERROR", "Invalid api_key_id")
        e = _validate_latlng(latlng, "latlng")
        if e: return _err("VALIDATION_ERROR", e)
        if result_type is not None:
            if not isinstance(result_type, list) or any(not isinstance(x, str) for x in result_type):
                return _err("VALIDATION_ERROR", "result_type must be an array of strings")
        if location_type is not None:
            if not isinstance(location_type, list) or any(not isinstance(x, str) for x in location_type):
                return _err("VALIDATION_ERROR", "location_type must be an array of strings")
        if language is not None and (not isinstance(language, str) or not language.strip()):
            return _err("VALIDATION_ERROR", "language must be a non-empty string")
        if dedupe is not None and not isinstance(dedupe, bool):
            return _err("VALIDATION_ERROR", "dedupe must be boolean")
        return None

    def _period_bounds(now, kind):
        if kind == "day":
            start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            end = start + datetime.timedelta(days=1)
            return start, end
        if kind == "month":
            start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            if start.month == 12:
                end = start.replace(year=start.year + 1, month=1)
            else:
                end = start.replace(month=start.month + 1)
            return start, end
        return None, None

    def _cache_key(tool_name, normalized_input):
        b = json.dumps({"tool_name": tool_name, "normalized_input": normalized_input}, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _estimate(tool_name, normalized_input):
        return 1, 0.005

    def _update_rollups(usage, ws_id, tool_name, now, add_req, add_units, add_cost):
        for period_type in ("day", "month"):
            ps, pe = _period_bounds(now, period_type)
            for tn in (tool_name, "*"):
                row = next((r for r in usage if r.get("workspace_id") == ws_id and r.get("period_type") == period_type and r.get("tool_name") == tn and r.get("period_start") == _iso(ps)), None)
                if not row:
                    row = {
                        "id": _gen_id("gmap_usage"),
                        "workspace_id": ws_id,
                        "period_start": _iso(ps),
                        "period_end": _iso(pe),
                        "period_type": period_type,
                        "tool_name": tn,
                        "request_count": 0,
                        "billable_units": 0,
                        "estimated_cost_usd": 0.0,
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    }
                    usage.append(row)
                row["request_count"] = int(row.get("request_count", 0)) + int(add_req)
                row["billable_units"] = int(row.get("billable_units", 0)) + int(add_units)
                row["estimated_cost_usd"] = float(row.get("estimated_cost_usd", 0.0)) + float(add_cost)
                row["updated_at"] = _iso(now)
        return usage

    def _projected_quota_exceeded(ws, now, add_req, add_cost):
        usage = _load("usage_rollups.json")
        day_start, _ = _period_bounds(now, "day")
        mon_start, _ = _period_bounds(now, "month")
        day_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "day" and r.get("tool_name") == "*" and r.get("period_start") == _iso(day_start)), None)
        mon_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "month" and r.get("tool_name") == "*" and r.get("period_start") == _iso(mon_start)), None)
        day_req = int((day_row or {}).get("request_count", 0)) + int(add_req)
        mon_req = int((mon_row or {}).get("request_count", 0)) + int(add_req)
        day_cost = float((day_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        mon_cost = float((mon_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        if day_req > int(ws.get("quota_daily_requests", 0)): return True
        if mon_req > int(ws.get("quota_monthly_requests", 0)): return True
        if day_cost > float(ws.get("quota_daily_cost_usd", 0.0)): return True
        if mon_cost > float(ws.get("quota_monthly_cost_usd", 0.0)): return True
        return False

    def _resolve(tool_name):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        conns = _load("provider_connections.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws: return None, None, None, _err("NOT_FOUND", "Workspace not found")
        key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if not key: return ws, None, None, _err("NOT_FOUND", "API key not found")
        if key.get("workspace_id") != ws.get("id"):
            return ws, key, None, _err("UNAUTHORIZED", "API key does not belong to workspace")
        conn = next((c for c in conns if c.get("workspace_id") == ws.get("id") and c.get("provider") == "google_maps_platform"), None)
        if not conn:
            return ws, key, None, _err("UNAUTHORIZED", "No provider connection configured for workspace")
        allowed = conn.get("allowed_endpoints")
        if not isinstance(allowed, list) or tool_name not in allowed:
            return ws, key, conn, _err("UNAUTHORIZED", "Endpoint not allowed for this workspace")
        return ws, key, conn, None

    v = _validate()
    if v:
        return v

    tool_name = "maps_reverse_geocode"
    now = _now()

