        return auth_err

    effective_language = language if language is not None else (ws.get("default_language") if ws else None)

    normalized_input = {
        "latlng": {"lat": float(latlng["lat"]), "lng": float(latlng["lng"])},
        "result_type": result_type if result_type is not None else None,
