        return hashlib.sha256(b).hexdigest()

    def _estimate(tool_name, normalized_input):
        # Use fields count as a characteristic affecting cost.
        fc = 0
        if isinstance(normalized_input, dict) and isinstance(normalized_input.get("fields"), list):
            fc = len(normalized_input["fields"])
        units = 1
        cost = 0.01 + 0.001 * max(0, fc - 1)
        return units, float(cost)

    def _update_rollups(usage, ws_id, tool_name, now, add_req, add_units, add_cost):
        for period_type in ("day", "month"):
            ps, pe = _period_bounds(now, period_type)
            for tn in (tool_name, "*"):
                row = next((r for r in usage if r.get("workspace_id") == ws_id and r.get("period_type") == period_type and r.get("tool_name") == tn and r.get("period_start") == _iso(ps)), None)
                if not row:
                    row = {
                        "id": _gen_id("gmap_usage"),
                        "workspace_id": ws_id,
                        "period_start": _iso(ps),
                        "period_end": _iso(pe),
                        "period_type": period_type,
                        "tool_name": tn,
                        "request_count": 0,
                        "billable_units": 0,
                        "estimated_cost_usd": 0.0,
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    }
                    usage.append(row)
                row["request_count"] = int(row.get("request_count", 0)) + int(add_req)
                row["billable_units"] = int(row.get("billable_units", 0)) + int(add_units)
                row["estimated_cost_usd"] = float(row.get("estimated_cost_usd", 0.0)) + float(add_cost)
                row["updated_at"] = _iso(now)
        return usage

    def _projected_quota_exceeded(ws, now, add_req, add_cost):
        usage = _load("usage_rollups.json")
        day_start, _ = _period_bounds(now, "day")
        mon_start, _ = _period_bounds(now, "month")
        day_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "day" and r.get("tool_name") == "*" and r.get("period_start") == _iso(day_start)), None)
        mon_row = next((r for r in usage if r.get("workspace_id") == ws["id"] and r.get("period_type") == "month" and r.get("tool_name") == "*" and r.get("period_start") == _iso(mon_start)), None)
        day_req = int((day_row or {}).get("request_count", 0)) + int(add_req)
        mon_req = int((mon_row or {}).get("request_count", 0)) + int(add_req)
        day_cost = float((day_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        mon_cost = float((mon_row or {}).get("estimated_cost_usd", 0.0)) + float(add_cost)
        if day_req > int(ws.get("quota_daily_requests", 0)): return True
        if mon_req > int(ws.get("quota_monthly_requests", 0)): return True
        if day_cost > float(ws.get("quota_daily_cost_usd", 0.0)): return True
        if mon_cost > float(ws.get("quota_monthly_cost_usd", 0.0)): return True
        return False

    def _resolve(tool_name):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        conns = _load("provider_connections.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws: return None, None, None, _err("NOT_FOUND", "Workspace not found")
        key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if not key: return ws, None, None, _err("NOT_FOUND", "API key not found")
        if key.get("workspace_id") != ws.get("id"):
            return ws, key, None, _err("UNAUTHORIZED", "API key does not belong to workspace")
        conn = next((c for c in conns if c.get("workspace_id") == ws.get("id") and c.get("provider") == "google_maps_platform"), None)
        if not conn:
            return ws, key, None, _err("UNAUTHORIZED", "No provider connection configured for workspace")
        allowed = conn.get("allowed_endpoints")
        if not isinstance(allowed, list) or tool_name not in allowed:
            return ws, key, conn, _err("UNAUTHORIZED", "Endpoint not allowed for this workspace")
        return ws, key, conn, None

    v = _validate()
    if v:
        return v

    tool_name = "maps_place_details"
    now = _now()
    ws, key, conn, auth_err = _resolve(tool_name)
    if auth_err and (ws is None or key is None):
        return auth_err

    effective_region = region if region is not None else (ws.get("default_region") if ws else None)
    effective_language = language if language is not None else (ws.get("default_language") if ws else None)

    normalized_input = {
        "place_id": place_id.strip(),
        "fields": fields if fields is not None else None,
        "language": effective_language,
        "region": effective_region,
        "session_token": session_token,
    }
    ck = _cache_key(tool_name, normalized_input)
    billable_units, est_cost = _estimate(tool_name, normalized_input)

    reqs = _load("maps_requests.json")
    usage = _load("usage_rollups.json")
    api_keys = _load("api_keys.json")

    req_id = _gen_id("gmap_req")
    row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "provider_connection_id": conn.get("id") if conn else "",
        "tool_name": tool_name,
        "status": "queued",
        "input": {
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "place_id": place_id,
            "fields": fields,
            "language": language,
            "region": region,
            "session_token": session_token,
            "dedupe": dedupe,
        },
        "normalized_input": normalized_input,
        "cache_key": ck,
        "provider_http_method": "GET",
        "provider_url": "https://maps.googleapis.com/maps/api/place/details/json",
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": int(billable_units),
        "estimated_cost_usd": float(est_cost),
        "deduped_from_request_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    final_status = None
    error_code = None
    error_message = None
    response = None
    provider_status_code = None
    deduped_from = None

    if ws.get("status") != "active":
        final_status, error_code, error_message = "failed", "workspace_inactive", "Workspace is not active"
    elif key.get("status") != "active":
        final_status, error_code, error_message = "failed", "api_key_revoked_or_expired", "API key is not active"
    else:
        exp = _parse_dt(key.get("expires_at"))
        if exp is not None and exp <= now:
            final_status, error_code, error_message = "failed", "api_key_revoked_or_expired", "API key is expired"

    if final_status is None:
        if conn is None:
            final_status, error_code, error_message = "failed", "provider_connection_error", "No provider connection available"
        else:
            if conn.get("status") == "disabled":
                final_status, error_code, error_message = "failed", "provider_connection_disabled", "Provider connection disabled"
            elif conn.get("status") == "error":
                final_status, error_code, error_message = "failed", "provider_connection_error", "Provider connection error"
            elif conn.get("status") != "active":
                final_status, error_code, error_message = "failed", "provider_connection_error", "Provider connection not active"

    if final_status is None and dedupe is True:
        hit = next((r for r in reqs if r.get("cache_key") == ck and r.get("tool_name") == tool_name and r.get("status") == "succeeded"), None)
        if hit:
            final_status = "succeeded"
            deduped_from = hit.get("id")
            response = hit.get("response")
            provider_status_code = hit.get("provider_status_code")

    if final_status is None:
        if _projected_quota_exceeded(ws, now, 1, est_cost):
            final_status, error_code, error_message = "failed", "quota_exceeded", "Quota exceeded"

    if final_status is None:
        final_status = "succeeded"
        provider_status_code = 200
        response = {
            "status": "OK",
            "result": {
                "place_id": normalized_input["place_id"],
                "name": "Demo Place",
                "formatted_address": "123 Demo St",
                "fields_returned": normalized_input["fields"] if normalized_input["fields"] is not None else "default",
            }
        }

    row["status"] = "running"
    row["updated_at"] = _iso(now)
    reqs.append(row)

    end = _now()
    latency_ms = int(max(0, round((time.time() - _t0) * 1000)))
    row["status"] = final_status
    row["error_code"] = error_code
    row["error_message"] = error_message
    row["response"] = response
    row["provider_status_code"] = provider_status_code
    row["latency_ms"] = latency_ms
    row["deduped_from_request_id"] = deduped_from
    row["updated_at"] = _iso(end)

    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = _iso(end)
            k["updated_at"] = _iso(end)
            break

    usage = _update_rollups(usage, workspace_id, tool_name, end, 1, billable_units, est_cost)

    _save("maps_requests.json", reqs)
    _save("usage_rollups.json", usage)
    _save("api_keys.json", api_keys)

    if final_status == "failed":
        return _err("QUOTA_EXCEEDED" if error_code == "quota_exceeded" else "UNAUTHORIZED" if error_code in ("workspace_inactive", "api_key_revoked_or_expired") else "CONFLICT",
                    "Request failed",
                    request_id=req_id,
                    error_code=error_code,
                    error_message=error_message)

    return {"request": row, "response": response, "deduped": bool(deduped_from)}

def maps_distance_matrix(workspace_id, api_key_id, origins, destinations, mode=None, language=None, region=None, units=None, departure_time=None, arrival_time=None, traffic_model=None, transit_mode=None, transit_routing_preference=None, avoid=None, dedupe=None, **_extra):
    import json, os, datetime, time, re, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    tool_name = "maps_distance_matrix"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode()).hexdigest()[:24].upper()}"

    def _record_request(maps_requests, workspaces, api_keys, provider_connections, req_row):
        # best-effort persistence, but do not throw
        try:
            maps_requests.append(req_row)
            _save("maps_requests.json", maps_requests)
        except Exception:
            return

    def _update_request(maps_requests, req_id, patch):
        for r in maps_requests:
            if r.get("id") == req_id:
                r.update(patch)
                r["updated_at"] = now_iso
                return True
        return False

    def _rollup_key(ws_id, period_type, period_start_iso, tool_bucket):
        return hashlib.sha256(f"{ws_id}|{period_type}|{period_start_iso}|{tool_bucket}".encode()).hexdigest()[:24].upper()

    def _period_bounds(dt, period_type):
        if period_type == "day":
            ps = dt.replace(hour=0, minute=0, second=0, microsecond=0)
            pe = ps + datetime.timedelta(days=1)
        else:
            ps = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            if ps.month == 12:
                pe = ps.replace(year=ps.year + 1, month=1)
            else:
                pe = ps.replace(month=ps.month + 1)
        return ps, pe

    def _ensure_rollup(usage_rollups, ws_id, period_type, ps, pe, tool_bucket):
        ps_iso = ps.isoformat()
        for row in usage_rollups:
            if row.get("workspace_id") == ws_id and row.get("period_type") == period_type and row.get("period_start") == ps_iso and row.get("tool_name") == tool_bucket:
                return row
        row = {
            "id": "gmap_roll_" + _rollup_key(ws_id, period_type, ps_iso, tool_bucket),
            "workspace_id": ws_id,
            "period_start": ps_iso,
            "period_end": pe.isoformat(),
            "period_type": period_type,
            "tool_name": tool_bucket,
            "request_count": 0,
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        usage_rollups.append(row)
        return row

    def _apply_rollups(ws_id, billable_units, estimated_cost_usd):
        usage_rollups = _load("usage_rollups.json")
        day_ps, day_pe = _period_bounds(now, "day")
        mon_ps, mon_pe = _period_bounds(now, "month")
        for period_type, ps, pe in (("day", day_ps, day_pe), ("month", mon_ps, mon_pe)):
            for bucket in (tool_name, "*"):
                rr = _ensure_rollup(usage_rollups, ws_id, period_type, ps, pe, bucket)
                rr["request_count"] = int(rr.get("request_count", 0)) + 1
                rr["billable_units"] = int(rr.get("billable_units", 0)) + int(billable_units)
                rr["estimated_cost_usd"] = float(rr.get("estimated_cost_usd", 0.0)) + float(estimated_cost_usd)
                rr["updated_at"] = now_iso
        _save("usage_rollups.json", usage_rollups)

    def _quota_totals(ws_id):
        usage_rollups = _load("usage_rollups.json")
        day_ps, _ = _period_bounds(now, "day")
        mon_ps, _ = _period_bounds(now, "month")
        day_ps_iso = day_ps.isoformat()
        mon_ps_iso = mon_ps.isoformat()
        day_row = None
        mon_row = None
        for r in usage_rollups:
            if r.get("workspace_id") != ws_id or r.get("tool_name") != "*":
                continue
            if r.get("period_type") == "day" and r.get("period_start") == day_ps_iso:
                day_row = r
            if r.get("period_type") == "month" and r.get("period_start") == mon_ps_iso:
                mon_row = r
        day_req = int(day_row.get("request_count", 0)) if day_row else 0
        mon_req = int(mon_row.get("request_count", 0)) if mon_row else 0
        day_cost = float(day_row.get("estimated_cost_usd", 0.0)) if day_row else 0.0
        mon_cost = float(mon_row.get("estimated_cost_usd", 0.0)) if mon_row else 0.0
        return day_req, mon_req, day_cost, mon_cost

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if not isinstance(origins, list) or len(origins) < 1 or any(not isinstance(x, str) or not x.strip() for x in origins):
        return _err("VALIDATION_ERROR", "origins must be a non-empty array of strings.")
    if not isinstance(destinations, list) or len(destinations) < 1 or any(not isinstance(x, str) or not x.strip() for x in destinations):
        return _err("VALIDATION_ERROR", "destinations must be a non-empty array of strings.")
    if mode is not None and mode not in ("driving", "walking", "bicycling", "transit"):
        return _err("VALIDATION_ERROR", "Invalid mode.")
    if units is not None and units not in ("metric", "imperial"):
        return _err("VALIDATION_ERROR", "Invalid units.")
    if traffic_model is not None and traffic_model not in ("best_guess", "pessimistic", "optimistic"):
        return _err("VALIDATION_ERROR", "Invalid traffic_model.")
    if transit_routing_preference is not None and transit_routing_preference not in ("less_walking", "fewer_transfers"):
        return _err("VALIDATION_ERROR", "Invalid transit_routing_preference.")
    if transit_mode is not None:
        if not isinstance(transit_mode, list) or any(not isinstance(x, str) or not x.strip() for x in transit_mode):
            return _err("VALIDATION_ERROR", "transit_mode must be an array of strings when provided.")
    if avoid is not None:
        if not isinstance(avoid, list) or any(not isinstance(x, str) or not x.strip() for x in avoid):
            return _err("VALIDATION_ERROR", "avoid must be an array of strings when provided.")
    if dedupe is not None and not isinstance(dedupe, bool):
        return _err("VALIDATION_ERROR", "dedupe must be boolean when provided.")
    if departure_time is not None and not isinstance(departure_time, str):
        return _err("VALIDATION_ERROR", "departure_time must be a string when provided.")
    if arrival_time is not None and not isinstance(arrival_time, str):
        return _err("VALIDATION_ERROR", "arrival_time must be a string when provided.")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string when provided.")
    if region is not None and not isinstance(region, str):
        return _err("VALIDATION_ERROR", "region must be a string when provided.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    provider_connections = _load("provider_connections.json")
    maps_requests = _load("maps_requests.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key:
        return _err("NOT_FOUND", "API key not found.")
    if key.get("workspace_id") != workspace_id:
        return _err("UNAUTHORIZED", "API key does not belong to the workspace.")

    # Choose a provider connection that can serve this endpoint for this workspace
    conn = None
    for c in provider_connections:
        if c.get("workspace_id") == workspace_id and c.get("provider") == "google_maps_platform":
            allowed = c.get("allowed_endpoints")
            if isinstance(allowed, list) and tool_name in allowed:
                conn = c
                break
    if not conn:
        return _err("UNAUTHORIZED", "No active provider connection is configured to allow this endpoint for the workspace.")

    # Defaults from workspace
    eff_language = language if language is not None else ws.get("default_language")
    eff_region = region if region is not None else ws.get("default_region")

    raw_input = {
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "origins": origins,
        "destinations": destinations,
        "mode": mode,
        "language": language,
        "region": region,
        "units": units,
        "departure_time": departure_time,
        "arrival_time": arrival_time,
        "traffic_model": traffic_model,
        "transit_mode": transit_mode,
        "transit_routing_preference": transit_routing_preference,
        "avoid": avoid,
        "dedupe": dedupe
    }

    # Normalize for cache and costing
    norm = {
        "origins": [s.strip() for s in origins],
        "destinations": [s.strip() for s in destinations],
        "mode": (mode or "driving"),
        "language": eff_language,
        "region": eff_region,
        "units": units,
        "departure_time": departure_time,
        "arrival_time": arrival_time,
        "traffic_model": traffic_model,
        "transit_mode": transit_mode[:] if isinstance(transit_mode, list) else None,
        "transit_routing_preference": transit_routing_preference,
        "avoid": avoid[:] if isinstance(avoid, list) else None
    }
    # canonicalize list order where order does not matter? For matrix, order matters; keep order.
    cache_key = hashlib.sha256((tool_name + "|" + json.dumps(norm, sort_keys=True, separators=(",", ":"))).encode("utf-8")).hexdigest()

    # Cost model (internal, deterministic): $0.005 per element, min 1 element.
    elements = max(1, len(origins) * len(destinations))
    billable_units = int(elements)
    estimated_cost_usd = float(max(0.0, elements * 0.005))

    # Create request row first (queued)
    req_id = _new_id("gmap_req_")
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "provider_connection_id": conn.get("id"),
        "tool_name": tool_name,
        "status": "queued",
        "input": raw_input,
        "normalized_input": norm,
        "cache_key": cache_key,
        "provider_http_method": "GET",
        "provider_url": "https://maps.googleapis.com/maps/api/distancematrix/json",
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": billable_units,
        "estimated_cost_usd": estimated_cost_usd,
        "deduped_from_request_id": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    _record_request(maps_requests, workspaces, api_keys, provider_connections, req_row)

    def _finalize_failed(code, message, provider_status_code=None):
        maps_requests2 = _load("maps_requests.json")
        _update_request(maps_requests2, req_id, {
            "status": "failed",
            "error_code": code,
            "error_message": message,
            "provider_status_code": provider_status_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("maps_requests.json", maps_requests2)
        _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
        return _err("QUOTA_EXCEEDED" if code == "quota_exceeded" else "UNAUTHORIZED" if code in ("workspace_inactive", "api_key_revoked_or_expired") else "CONFLICT" if code.startswith("provider_connection_") else "CONFLICT", message, request_id=req_id)

    # Preconditions
    if ws.get("status") != "active":
        return _finalize_failed("workspace_inactive", "Workspace is not active.")
    if key.get("status") != "active":
        return _finalize_failed("api_key_revoked_or_expired", "API key is revoked or inactive.")
    exp = _parse_dt(key.get("expires_at"))
    if exp is not None and exp <= now:
        return _finalize_failed("api_key_revoked_or_expired", "API key is expired.")
    if conn.get("status") != "active":
        if conn.get("status") == "disabled":
            return _finalize_failed("provider_connection_disabled", "Provider connection is disabled.")
        return _finalize_failed("provider_connection_error", "Provider connection is in error state.")

    # Quota enforcement (projected totals)
    day_req, mon_req, day_cost, mon_cost = _quota_totals(workspace_id)
    qdr = int(ws.get("quota_daily_requests", 0))
    qmr = int(ws.get("quota_monthly_requests", 0))
    qdc = float(ws.get("quota_daily_cost_usd", 0.0))
    qmc = float(ws.get("quota_monthly_cost_usd", 0.0))
    if (qdr >= 0 and day_req + 1 > qdr) or (qmr >= 0 and mon_req + 1 > qmr) or (qdc >= 0 and day_cost + estimated_cost_usd > qdc) or (qmc >= 0 and mon_cost + estimated_cost_usd > qmc):
        return _finalize_failed("quota_exceeded", "Quota exceeded for workspace.")

    # Dedupe
    if dedupe is True:
        cached = None
        for r in maps_requests:
            if r.get("cache_key") == cache_key and r.get("tool_name") == tool_name and r.get("status") == "succeeded":
                cached = r
                break
        if cached and isinstance(cached.get("response"), (dict, list)):
            maps_requests2 = _load("maps_requests.json")
            _update_request(maps_requests2, req_id, {
                "status": "succeeded",
                "response": cached.get("response"),
                "deduped_from_request_id": cached.get("id"),
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("maps_requests.json", maps_requests2)
            # update last_used_at
            api_keys2 = _load("api_keys.json")
            for k in api_keys2:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", api_keys2)
            _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
            return {
                "request": next((r for r in maps_requests2 if r.get("id") == req_id), None),
                "data": cached.get("response"),
                "deduped": True
            }

    # Execute "provider call" offline: deterministic synthetic response
    maps_requests2 = _load("maps_requests.json")
    _update_request(maps_requests2, req_id, {"status": "running"})
    _save("maps_requests.json", maps_requests2)

    # Build matrix
    rows = []
    base_seconds = {"driving": 600, "walking": 1800, "bicycling": 1200, "transit": 1500}.get((mode or "driving"), 600)
    for oi, o in enumerate(origins):
        elements_list = []
        for di, d in enumerate(destinations):
            # deterministic pseudo-distance
            h = int(hashlib.sha256(f"{o}|{d}|{mode}".encode("utf-8")).hexdigest()[:8], 16)
            km = 1.0 + (h % 50000) / 1000.0  # 1..51km
            meters = int(km * 1000)
            sec = int(base_seconds + (meters / 1000.0) * (120 if (mode or "driving") == "driving" else 400))
            elements_list.append({
                "status": "OK",
                "distance": {"value": meters, "text": f"{km:.1f} km"},
                "duration": {"value": sec, "text": f"{max(1,int(sec/60))} mins"}
            })
        rows.append({"elements": elements_list})

    response = {
        "status": "OK",
        "origin_addresses": origins,
        "destination_addresses": destinations,
        "rows": rows,
        "language": eff_language,
        "region": eff_region,
        "units": units
    }

    latency_ms = int((time.time() - t0) * 1000)
    maps_requests3 = _load("maps_requests.json")
    _update_request(maps_requests3, req_id, {
        "status": "succeeded",
        "response": response,
        "provider_status_code": 200,
        "provider_request_id": "offline-" + hashlib.sha256(req_id.encode()).hexdigest()[:16],
        "latency_ms": latency_ms
    })
    _save("maps_requests.json", maps_requests3)

    api_keys2 = _load("api_keys.json")
    for k in api_keys2:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys2)

    _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
    return {
        "request": next((r for r in maps_requests3 if r.get("id") == req_id), None),
        "data": response,
        "deduped": False
    }

def maps_directions(workspace_id, api_key_id, origin, destination, mode=None, waypoints=None, alternatives=None, avoid=None, language=None, region=None, units=None, departure_time=None, arrival_time=None, traffic_model=None, transit_mode=None, transit_routing_preference=None, dedupe=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()
    tool_name = "maps_directions"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode()).hexdigest()[:24].upper()}"

    def _period_bounds(dt, period_type):
        if period_type == "day":
            ps = dt.replace(hour=0, minute=0, second=0, microsecond=0)
            pe = ps + datetime.timedelta(days=1)
        else:
            ps = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            if ps.month == 12:
                pe = ps.replace(year=ps.year + 1, month=1)
            else:
                pe = ps.replace(month=ps.month + 1)
        return ps, pe

    def _rollup_key(ws_id, period_type, period_start_iso, tool_bucket):
        return hashlib.sha256(f"{ws_id}|{period_type}|{period_start_iso}|{tool_bucket}".encode()).hexdigest()[:24].upper()

    def _ensure_rollup(usage_rollups, ws_id, period_type, ps, pe, tool_bucket):
        ps_iso = ps.isoformat()
        for row in usage_rollups:
            if row.get("workspace_id") == ws_id and row.get("period_type") == period_type and row.get("period_start") == ps_iso and row.get("tool_name") == tool_bucket:
                return row
        row = {
            "id": "gmap_roll_" + _rollup_key(ws_id, period_type, ps_iso, tool_bucket),
            "workspace_id": ws_id,
            "period_start": ps_iso,
            "period_end": pe.isoformat(),
            "period_type": period_type,
            "tool_name": tool_bucket,
            "request_count": 0,
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        usage_rollups.append(row)
        return row

    def _apply_rollups(ws_id, billable_units, estimated_cost_usd):
        usage_rollups = _load("usage_rollups.json")
        day_ps, day_pe = _period_bounds(now, "day")
        mon_ps, mon_pe = _period_bounds(now, "month")
        for period_type, ps, pe in (("day", day_ps, day_pe), ("month", mon_ps, mon_pe)):
            for bucket in (tool_name, "*"):
                rr = _ensure_rollup(usage_rollups, ws_id, period_type, ps, pe, bucket)
                rr["request_count"] = int(rr.get("request_count", 0)) + 1
                rr["billable_units"] = int(rr.get("billable_units", 0)) + int(billable_units)
                rr["estimated_cost_usd"] = float(rr.get("estimated_cost_usd", 0.0)) + float(estimated_cost_usd)
                rr["updated_at"] = now_iso
        _save("usage_rollups.json", usage_rollups)

    def _quota_totals(ws_id):
        usage_rollups = _load("usage_rollups.json")
        day_ps, _ = _period_bounds(now, "day")
        mon_ps, _ = _period_bounds(now, "month")
        day_ps_iso = day_ps.isoformat()
        mon_ps_iso = mon_ps.isoformat()
        day_row = None
        mon_row = None
        for r in usage_rollups:
            if r.get("workspace_id") != ws_id or r.get("tool_name") != "*":
                continue
            if r.get("period_type") == "day" and r.get("period_start") == day_ps_iso:
                day_row = r
            if r.get("period_type") == "month" and r.get("period_start") == mon_ps_iso:
                mon_row = r
        day_req = int(day_row.get("request_count", 0)) if day_row else 0
        mon_req = int(mon_row.get("request_count", 0)) if mon_row else 0
        day_cost = float(day_row.get("estimated_cost_usd", 0.0)) if day_row else 0.0
        mon_cost = float(mon_row.get("estimated_cost_usd", 0.0)) if mon_row else 0.0
        return day_req, mon_req, day_cost, mon_cost

    def _update_request(maps_requests, req_id, patch):
        for r in maps_requests:
            if r.get("id") == req_id:
                r.update(patch)
                r["updated_at"] = now_iso
                return True
        return False

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if not isinstance(origin, str) or not origin.strip():
        return _err("VALIDATION_ERROR", "origin must be a non-empty string.")
    if not isinstance(destination, str) or not destination.strip():
        return _err("VALIDATION_ERROR", "destination must be a non-empty string.")
    if mode is not None and mode not in ("driving", "walking", "bicycling", "transit"):
        return _err("VALIDATION_ERROR", "Invalid mode.")
    if units is not None and units not in ("metric", "imperial"):
        return _err("VALIDATION_ERROR", "Invalid units.")
    if traffic_model is not None and traffic_model not in ("best_guess", "pessimistic", "optimistic"):
        return _err("VALIDATION_ERROR", "Invalid traffic_model.")
    if transit_routing_preference is not None and transit_routing_preference not in ("less_walking", "fewer_transfers"):
        return _err("VALIDATION_ERROR", "Invalid transit_routing_preference.")
    if waypoints is not None:
        if not isinstance(waypoints, list) or any(not isinstance(x, str) or not x.strip() for x in waypoints):
            return _err("VALIDATION_ERROR", "waypoints must be an array of strings when provided.")
    if avoid is not None:
        if not isinstance(avoid, list) or any(not isinstance(x, str) or not x.strip() for x in avoid):
            return _err("VALIDATION_ERROR", "avoid must be an array of strings when provided.")
    if alternatives is not None and not isinstance(alternatives, bool):
        return _err("VALIDATION_ERROR", "alternatives must be boolean when provided.")
    if dedupe is not None and not isinstance(dedupe, bool):
        return _err("VALIDATION_ERROR", "dedupe must be boolean when provided.")
    if departure_time is not None and not isinstance(departure_time, str):
        return _err("VALIDATION_ERROR", "departure_time must be a string when provided.")
    if arrival_time is not None and not isinstance(arrival_time, str):
        return _err("VALIDATION_ERROR", "arrival_time must be a string when provided.")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string when provided.")
    if region is not None and not isinstance(region, str):
        return _err("VALIDATION_ERROR", "region must be a string when provided.")
    if transit_mode is not None:
        if not isinstance(transit_mode, list) or any(not isinstance(x, str) or not x.strip() for x in transit_mode):
            return _err("VALIDATION_ERROR", "transit_mode must be an array of strings when provided.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    provider_connections = _load("provider_connections.json")
    maps_requests = _load("maps_requests.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key:
        return _err("NOT_FOUND", "API key not found.")
    if key.get("workspace_id") != workspace_id:
        return _err("UNAUTHORIZED", "API key does not belong to the workspace.")

    conn = None
    for c in provider_connections:
        if c.get("workspace_id") == workspace_id and c.get("provider") == "google_maps_platform":
            allowed = c.get("allowed_endpoints")
            if isinstance(allowed, list) and tool_name in allowed:
                conn = c
                break
    if not conn:
        return _err("UNAUTHORIZED", "No active provider connection is configured to allow this endpoint for the workspace.")

    eff_language = language if language is not None else ws.get("default_language")
    eff_region = region if region is not None else ws.get("default_region")

    raw_input = {
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "origin": origin,
        "destination": destination,
        "mode": mode,
        "waypoints": waypoints,
        "alternatives": alternatives,
        "avoid": avoid,
        "language": language,
        "region": region,
        "units": units,
        "departure_time": departure_time,
        "arrival_time": arrival_time,
        "traffic_model": traffic_model,
        "transit_mode": transit_mode,
        "transit_routing_preference": transit_routing_preference,
        "dedupe": dedupe
    }

    wp = waypoints[:] if isinstance(waypoints, list) else []
    norm = {
        "origin": origin.strip(),
        "destination": destination.strip(),
        "mode": (mode or "driving"),
        "waypoints": [w.strip() for w in wp],
        "alternatives": bool(alternatives) if alternatives is not None else False,
        "avoid": [a.strip() for a in avoid] if isinstance(avoid, list) else None,
        "language": eff_language,
        "region": eff_region,
        "units": units,
        "departure_time": departure_time,
        "arrival_time": arrival_time,
        "traffic_model": traffic_model,
        "transit_mode": transit_mode[:] if isinstance(transit_mode, list) else None,
        "transit_routing_preference": transit_routing_preference
    }
    cache_key = hashlib.sha256((tool_name + "|" + json.dumps(norm, sort_keys=True, separators=(",", ":"))).encode("utf-8")).hexdigest()

    # Cost model: base $0.01 + $0.002 per waypoint
    billable_units = int(max(1, 1 + len(wp)))
    estimated_cost_usd = float(max(0.0, 0.01 + len(wp) * 0.002))

    req_id = _new_id("gmap_req_")
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "provider_connection_id": conn.get("id"),
        "tool_name": tool_name,
        "status": "queued",
        "input": raw_input,
        "normalized_input": norm,
        "cache_key": cache_key,
        "provider_http_method": "GET",
        "provider_url": "https://maps.googleapis.com/maps/api/directions/json",
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": billable_units,
        "estimated_cost_usd": estimated_cost_usd,
        "deduped_from_request_id": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    maps_requests.append(req_row)
    _save("maps_requests.json", maps_requests)

    def _finalize_failed(code, message, provider_status_code=None):
        maps_requests2 = _load("maps_requests.json")
        _update_request(maps_requests2, req_id, {
            "status": "failed",
            "error_code": code,
            "error_message": message,
            "provider_status_code": provider_status_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("maps_requests.json", maps_requests2)
        _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
        return _err("QUOTA_EXCEEDED" if code == "quota_exceeded" else "UNAUTHORIZED" if code in ("workspace_inactive", "api_key_revoked_or_expired") else "CONFLICT", message, request_id=req_id)

    if ws.get("status") != "active":
        return _finalize_failed("workspace_inactive", "Workspace is not active.")
    if key.get("status") != "active":
        return _finalize_failed("api_key_revoked_or_expired", "API key is revoked or inactive.")
    exp = _parse_dt(key.get("expires_at"))
    if exp is not None and exp <= now:
        return _finalize_failed("api_key_revoked_or_expired", "API key is expired.")
    if conn.get("status") != "active":
        if conn.get("status") == "disabled":
            return _finalize_failed("provider_connection_disabled", "Provider connection is disabled.")
        return _finalize_failed("provider_connection_error", "Provider connection is in error state.")

    day_req, mon_req, day_cost, mon_cost = _quota_totals(workspace_id)
    qdr = int(ws.get("quota_daily_requests", 0))
    qmr = int(ws.get("quota_monthly_requests", 0))
    qdc = float(ws.get("quota_daily_cost_usd", 0.0))
    qmc = float(ws.get("quota_monthly_cost_usd", 0.0))
    if (qdr >= 0 and day_req + 1 > qdr) or (qmr >= 0 and mon_req + 1 > qmr) or (qdc >= 0 and day_cost + estimated_cost_usd > qdc) or (qmc >= 0 and mon_cost + estimated_cost_usd > qmc):
        return _finalize_failed("quota_exceeded", "Quota exceeded for workspace.")

    if dedupe is True:
        cached = None
        for r in maps_requests:
            if r.get("cache_key") == cache_key and r.get("tool_name") == tool_name and r.get("status") == "succeeded":
                cached = r
                break
        if cached and isinstance(cached.get("response"), (dict, list)):
            maps_requests2 = _load("maps_requests.json")
            _update_request(maps_requests2, req_id, {
                "status": "succeeded",
                "response": cached.get("response"),
                "deduped_from_request_id": cached.get("id"),
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("maps_requests.json", maps_requests2)
            api_keys2 = _load("api_keys.json")
            for k in api_keys2:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", api_keys2)
            _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
            return {
                "request": next((r for r in maps_requests2 if r.get("id") == req_id), None),
                "data": cached.get("response"),
                "deduped": True
            }

    maps_requests2 = _load("maps_requests.json")
    _update_request(maps_requests2, req_id, {"status": "running"})
    _save("maps_requests.json", maps_requests2)

    # Offline deterministic route
    seed = hashlib.sha256(f"{origin}|{destination}|{norm['mode']}|{','.join(norm['waypoints'])}".encode("utf-8")).hexdigest()
    meters = 1000 + (int(seed[:8], 16) % 250000)  # 1km..251km
    base = {"driving": 60, "walking": 250, "bicycling": 180, "transit": 220}.get(norm["mode"], 60)
    seconds = int(meters / 1000.0 * base) + 300 + len(norm["waypoints"]) * 120
    route = {
        "summary": "Offline route",
        "legs": [{
            "start_address": origin,
            "end_address": destination,
            "distance": {"value": meters, "text": f"{meters/1000.0:.1f} km"},
            "duration": {"value": seconds, "text": f"{max(1,int(seconds/60))} mins"},
            "steps": []
        }],
        "warnings": [],
        "waypoint_order": list(range(len(norm["waypoints"])))
    }
    routes = [route]
    if norm["alternatives"]:
        meters2 = int(meters * 1.08)
        seconds2 = int(seconds * 1.12)
        routes.append({
            "summary": "Offline alternative route",
            "legs": [{
                "start_address": origin,
                "end_address": destination,
                "distance": {"value": meters2, "text": f"{meters2/1000.0:.1f} km"},
                "duration": {"value": seconds2, "text": f"{max(1,int(seconds2/60))} mins"},
                "steps": []
            }],
            "warnings": [],
            "waypoint_order": list(range(len(norm["waypoints"])))
        })

    response = {
        "status": "OK",
        "geocoded_waypoints": [],
        "routes": routes,
        "language": eff_language,
        "region": eff_region,
        "units": units
    }

    maps_requests3 = _load("maps_requests.json")
    _update_request(maps_requests3, req_id, {
        "status": "succeeded",
        "response": response,
        "provider_status_code": 200,
        "provider_request_id": "offline-" + hashlib.sha256(req_id.encode()).hexdigest()[:16],
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("maps_requests.json", maps_requests3)

    api_keys2 = _load("api_keys.json")
    for k in api_keys2:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys2)

    _apply_rollups(workspace_id, billable_units, estimated_cost_usd)
    return {
        "request": next((r for r in maps_requests3 if r.get("id") == req_id), None),
        "data": response,
        "deduped": False
    }

def maps_list_workspaces(api_key_id, status=None, query=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string when provided.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    maps_requests = _load("maps_requests.json")
    provider_connections = _load("provider_connections.json")

    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Invalid API key.")
    ws_id = key.get("workspace_id")
    if not ws_id:
        return _err("UNAUTHORIZED", "API key is not associated with a workspace.")

    # Record invocation as a request log (tool invocation must create maps_requests row)
    req_id = "gmap_req_" + (re.sub(r"[^0-9A-F]", "", base64.b16encode(os.urandom(12)).decode("ascii"))[:24])
    # Choose a provider connection if exists, else still log with placeholder but must satisfy foreign key -> pick any matching ws+provider if exists
    conn_id = None
    for c in provider_connections:
        if c.get("workspace_id") == ws_id and c.get("provider") == "google_maps_platform":
            conn_id = c.get("id")
            break
    if conn_id is None:
        # cannot satisfy FK; refuse as unauthorized per contract
        return _err("UNAUTHORIZED", "No provider connection available for request logging context.")
    req_row = {
        "id": req_id,
        "workspace_id": ws_id,
        "api_key_id": api_key_id,
        "provider_connection_id": conn_id,
        "tool_name": "maps_search_places",  # placeholder not allowed; must be this tool but enum excludes list tool.
        "status": "failed",
        "input": {"api_key_id": api_key_id, "status": status, "query": query, "limit": limit, "cursor": cursor},
        "normalized_input": None,
        "cache_key": None,
        "provider_http_method": None,
        "provider_url": None,
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": "validation_error",
        "error_message": "Internal: maps_list_workspaces is not a billable maps_requests tool.",
        "latency_ms": int((time.time() - t0) * 1000),
        "billable_units": 0,
        "estimated_cost_usd": 0.0,
        "deduped_from_request_id": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    # The schema restricts tool_name enum to maps_* tools only; do not write invalid row.
    # Instead, keep observable dynamics via updating api_key last_used_at only.
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Cursor handling: base64 of json {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Scope: visible to caller => only its own workspace
    rows = [w for w in workspaces if w.get("id") == ws_id]
    if status:
        rows = [w for w in rows if w.get("status") == status]
    if query:
        q = query.strip().lower()
        rows = [w for w in rows if q in (w.get("name") or "").lower()]

    # sort by created_at then id
    def _dt(s):
        try:
            if isinstance(s, str):
                ss = s[:-1] + "+00:00" if s.endswith("Z") else s
                d = datetime.datetime.fromisoformat(ss)
                if d.tzinfo is None:
                    d = d.replace(tzinfo=datetime.timezone.utc)
                return d
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    rows.sort(key=lambda r: (_dt(r.get("created_at")), r.get("id") or ""))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def maps_create_workspace(api_key_id, name, default_region=None, default_language=None, quota_daily_requests=None, quota_monthly_requests=None, quota_daily_cost_usd=None, quota_monthly_cost_usd=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "maps_create_workspace"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        h = hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24].upper()
        return f"{prefix}_{h}"

    def _coerce_int(x, field):
        if x is None:
            return None
        if isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"{field} must be an integer >= 0")
        if not isinstance(x, int):
            return _err("VALIDATION_ERROR", f"{field} must be an integer >= 0")
        if x < 0:
            return _err("VALIDATION_ERROR", f"{field} must be an integer >= 0")
        return x

    def _coerce_num(x, field):
        if x is None:
            return None
        if isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"{field} must be a number >= 0")
        if not isinstance(x, (int, float)):
            return _err("VALIDATION_ERROR", f"{field} must be a number >= 0")
        if float(x) < 0:
            return _err("VALIDATION_ERROR", f"{field} must be a number >= 0")
        return float(x)

    # Validate inputs (tool schema)
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id (expected pattern ^gmap_key_[0-9A-Z]{18,}$).")
    if not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 120:
        return _err("VALIDATION_ERROR", "Invalid name (must be 1-120 characters).")
    if default_region is not None and not isinstance(default_region, str):
        return _err("VALIDATION_ERROR", "default_region must be a string if provided.")
    if default_language is not None and not isinstance(default_language, str):
        return _err("VALIDATION_ERROR", "default_language must be a string if provided.")

    qdr = _coerce_int(quota_daily_requests, "quota_daily_requests")
    if isinstance(qdr, dict) and "error" in qdr:
        return qdr
    qmr = _coerce_int(quota_monthly_requests, "quota_monthly_requests")
    if isinstance(qmr, dict) and "error" in qmr:
        return qmr
    qdc = _coerce_num(quota_daily_cost_usd, "quota_daily_cost_usd")
    if isinstance(qdc, dict) and "error" in qdc:
        return qdc
    qmc = _coerce_num(quota_monthly_cost_usd, "quota_monthly_cost_usd")
    if isinstance(qmc, dict) and "error" in qmc:
        return qmc

    # Load datastore
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    provider_connections = _load("provider_connections.json")
    maps_requests = _load("maps_requests.json")

    # Authenticate by api_key_id (explicit credential parameter)
    caller_key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not caller_key:
        # record attempt if possible: no workspace id available, cannot satisfy business rule for maps_requests FK
        return _err("UNAUTHORIZED", "API key not found.")
    caller_ws_id = caller_key.get("workspace_id")
    caller_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == caller_ws_id), None)
    if not caller_ws:
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace.")
    # choose an existing provider connection for request logging FK (even though this tool doesn't call provider)
    pcn = next((c for c in provider_connections if isinstance(c, dict) and c.get("workspace_id") == caller_ws_id and c.get("provider") == "google_maps_platform"), None)
    if not pcn:
        # cannot create maps_requests row without provider_connection_id FK
        return _err("UNAUTHORIZED", "No provider connection available for this workspace.")
    provider_connection_id = pcn.get("id")

    # Create maps_requests row for this tool invocation (business rule)
    now = _utcnow()
    req_row = {
        "id": _new_id("gmap_req"),
        "workspace_id": caller_ws_id,
        "api_key_id": api_key_id,
        "provider_connection_id": provider_connection_id,
        "tool_name": tool_name,  # intentionally stores tool name invoked
        "status": "succeeded",
        "input": {
            "api_key_id": api_key_id,
            "name": name,
            "default_region": default_region,
            "default_language": default_language,
            "quota_daily_requests": quota_daily_requests,
            "quota_monthly_requests": quota_monthly_requests,
            "quota_daily_cost_usd": quota_daily_cost_usd,
            "quota_monthly_cost_usd": quota_monthly_cost_usd,
        },
        "normalized_input": None,
        "cache_key": None,
        "provider_http_method": None,
        "provider_url": None,
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": 0,
        "estimated_cost_usd": 0.0,
        "deduped_from_request_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Enforce unique(name) for workspaces
    normalized_name = name.strip()
    if any(isinstance(w, dict) and isinstance(w.get("name"), str) and w.get("name") == normalized_name for w in workspaces):
        req_row["status"] = "failed"
        req_row["error_code"] = "conflict"
        req_row["error_message"] = "Workspace name already exists (unique(name))."
        req_row["updated_at"] = _iso(_utcnow())
        req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
        maps_requests.append(req_row)
        _save("maps_requests.json", maps_requests)
        return _err("CONFLICT", "Workspace name already exists (unique(name)).", request_id=req_row["id"])

    # Apply defaults for quotas when omitted: inherit from caller's workspace caps
    if qdr is None:
        qdr = int(caller_ws.get("quota_daily_requests", 0) or 0)
    if qmr is None:
        qmr = int(caller_ws.get("quota_monthly_requests", 0) or 0)
    if qdc is None:
        qdc = float(caller_ws.get("quota_daily_cost_usd", 0.0) or 0.0)
    if qmc is None:
        qmc = float(caller_ws.get("quota_monthly_cost_usd", 0.0) or 0.0)

    # Create workspace
    ws_now = _utcnow()
    ws_row = {
        "id": _new_id("gmap_ws"),
        "name": normalized_name,
        "status": "active",
        "default_region": default_region,
        "default_language": default_language,
        "quota_daily_requests": qdr,
        "quota_monthly_requests": qmr,
        "quota_daily_cost_usd": qdc,
        "quota_monthly_cost_usd": qmc,
        "created_at": _iso(ws_now),
        "updated_at": _iso(ws_now),
    }
    workspaces.append(ws_row)
    _save("workspaces.json", workspaces)

    req_row["response"] = {"workspace_id": ws_row["id"]}
    req_row["updated_at"] = _iso(_utcnow())
    req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
    maps_requests.append(req_row)
    _save("maps_requests.json", maps_requests)

    return {"workspace": ws_row}

def maps_update_workspace(api_key_id, workspace_id, name=None, default_region=None, default_language=None, quota_daily_requests=None, quota_monthly_requests=None, quota_daily_cost_usd=None, quota_monthly_cost_usd=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "maps_update_workspace"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_req_id():
        h = hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24].upper()
        return "gmap_req_" + h

    def _append_maps_request(maps_requests, status_r, ws_id_r, api_key_id_r, error_code=None, error_message=None, response=None):
        now_iso = _now_iso()
        row = {
            "id": _new_req_id(),
            "workspace_id": ws_id_r,
            "api_key_id": api_key_id_r,
            "provider_connection_id": "gmap_pcn_NONE",
            "tool_name": tool_name,
            "status": status_r,
            "input": {
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "name": name,
                "default_region": default_region,
                "default_language": default_language,
                "quota_daily_requests": quota_daily_requests,
                "quota_monthly_requests": quota_monthly_requests,
                "quota_daily_cost_usd": quota_daily_cost_usd,
                "quota_monthly_cost_usd": quota_monthly_cost_usd,
                "status": status,
            },
            "normalized_input": None,
            "cache_key": None,
            "provider_http_method": None,
            "provider_url": None,
            "provider_status_code": None,
            "provider_request_id": None,
            "response": response,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "deduped_from_request_id": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        maps_requests.append(row)
        return row

    # ---- Validate inputs
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id format.")
    if not isinstance(workspace_id, str) or not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 120)):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 120 characters.")
    if default_region is not None and not isinstance(default_region, str):
        return _err("VALIDATION_ERROR", "default_region must be a string when provided.")
    if default_language is not None and not isinstance(default_language, str):
        return _err("VALIDATION_ERROR", "default_language must be a string when provided.")
    for fn, v in (("quota_daily_requests", quota_daily_requests), ("quota_monthly_requests", quota_monthly_requests)):
        if v is not None and (not isinstance(v, int) or v < 0):
            return _err("VALIDATION_ERROR", f"{fn} must be an integer >= 0 when provided.")
    for fn, v in (("quota_daily_cost_usd", quota_daily_cost_usd), ("quota_monthly_cost_usd", quota_monthly_cost_usd)):
        if v is not None and (not isinstance(v, (int, float)) or float(v) < 0):
            return _err("VALIDATION_ERROR", f"{fn} must be a number >= 0 when provided.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted.")

    # ---- Load store
    workspaces = _load("workspaces.json") or []
    api_keys = _load("api_keys.json") or []
    maps_requests = _load("maps_requests.json") or []

    # ---- Authenticate by API key id (no hashes)
    caller_key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not caller_key:
        _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="api_key_revoked_or_expired", error_message="API key not found.")
        _save("maps_requests.json", maps_requests)
        return _err("UNAUTHORIZED", "API key not found.")

    # authorize: allow if caller_key belongs to target workspace
    if caller_key.get("workspace_id") != workspace_id:
        _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="unauthorized", error_message="API key does not belong to the workspace.")
        _save("maps_requests.json", maps_requests)
        return _err("UNAUTHORIZED", "API key does not belong to the workspace.")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="not_found", error_message="Workspace not found.")
        _save("maps_requests.json", maps_requests)
        return _err("NOT_FOUND", "Workspace not found.")

    if ws.get("status") == "deleted":
        _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="invalid_transition", error_message="Cannot update a deleted workspace.")
        _save("maps_requests.json", maps_requests)
        return _err("INVALID_TRANSITION", "Cannot update a deleted workspace.")

    # ---- Apply updates
    changed = False
    if name is not None and name != ws.get("name"):
        if any((w.get("name") == name and w.get("id") != workspace_id) for w in workspaces):
            _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="conflict", error_message="Workspace name already exists (unique(name)).")
            _save("maps_requests.json", maps_requests)
            return _err("CONFLICT", "Workspace name already exists (unique(name)).")
        ws["name"] = name
        changed = True

    if default_region is not None:
        ws["default_region"] = default_region
        changed = True
    if default_language is not None:
        ws["default_language"] = default_language
        changed = True
    if quota_daily_requests is not None:
        ws["quota_daily_requests"] = int(quota_daily_requests)
        changed = True
    if quota_monthly_requests is not None:
        ws["quota_monthly_requests"] = int(quota_monthly_requests)
        changed = True
    if quota_daily_cost_usd is not None:
        ws["quota_daily_cost_usd"] = float(quota_daily_cost_usd)
        changed = True
    if quota_monthly_cost_usd is not None:
        ws["quota_monthly_cost_usd"] = float(quota_monthly_cost_usd)
        changed = True

    if status is not None and status != ws.get("status"):
        transitions = {"active": {"suspended", "deleted"}, "suspended": {"active", "deleted"}, "deleted": set()}
        cur = ws.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="invalid_transition", error_message=f"Illegal status transition {cur} → {status}.")
            _save("maps_requests.json", maps_requests)
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} → {status}.")
        ws["status"] = status
        changed = True

    if not changed:
        _append_maps_request(maps_requests, "failed", workspace_id, api_key_id, error_code="not_found", error_message="No changes to apply.")
        _save("maps_requests.json", maps_requests)
        return _err("NOT_FOUND", "No changes to apply.")

    ws["updated_at"] = _now_iso()

    req = _append_maps_request(maps_requests, "succeeded", workspace_id, api_key_id, response=ws)

    _save("workspaces.json", workspaces)
    _save("maps_requests.json", maps_requests)
    return {"workspace": ws, "request": req}

def maps_create_api_key(api_key_id, workspace_id, name, expires_at=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "maps_create_api_key"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _record_request(status_r, api_key_row=None, workspace_id_r=None, error_code=None, error_message=None, response=None, input_payload=None):
        maps_requests = _load("maps_requests.json")
        now = _now_iso()
        rid = "gmap_req_" + secrets.token_hex(12).upper()
        maps_requests.append({
            "id": rid,
            "workspace_id": workspace_id_r if workspace_id_r is not None else (api_key_row.get("workspace_id") if api_key_row else "gmap_ws_UNKNOWN"),
            "api_key_id": api_key_row.get("id") if api_key_row else (api_key_id if isinstance(api_key_id, str) else "gmap_key_UNKNOWN"),
            "provider_connection_id": "gmap_conn_NONE",
            "tool_name": tool_name,
            "status": status_r,
            "input": input_payload if isinstance(input_payload, dict) else {},
            "normalized_input": None,
            "cache_key": None,
            "provider_http_method": None,
            "provider_url": None,
            "provider_status_code": None,
            "provider_request_id": None,
            "response": response,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "deduped_from_request_id": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("maps_requests.json", maps_requests)
        return rid

    raw_payload = {"api_key_id": api_key_id, "workspace_id": workspace_id, "name": name, "expires_at": expires_at}

    if not (isinstance(api_key_id, str) and re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id or "")):
        _record_request("failed", None, workspace_id_r=workspace_id, error_code="validation_error", error_message="Invalid api_key_id.", input_payload=raw_payload)
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if not (isinstance(workspace_id, str) and re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id or "")):
        api_keys = _load("api_keys.json")
        auth_key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="validation_error", error_message="Invalid workspace_id.", input_payload=raw_payload)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(name, str) or not (1 <= len(name) <= 120):
        api_keys = _load("api_keys.json")
        auth_key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="validation_error", error_message="Invalid name.", input_payload=raw_payload)
        return _err("VALIDATION_ERROR", "Invalid name.")

    exp_dt = _parse_dt(expires_at) if expires_at is not None else None
    if expires_at is not None and exp_dt is None:
        api_keys = _load("api_keys.json")
        auth_key = next((k for k in api_keys if k.get("id") == api_key_id), None)
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="validation_error", error_message="Invalid expires_at date-time.", input_payload=raw_payload)
        return _err("VALIDATION_ERROR", "Invalid expires_at date-time.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    auth_key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not auth_key:
        _record_request("failed", None, workspace_id_r=workspace_id, error_code="unauthorized", error_message="API key not found.", input_payload=raw_payload)
        return _err("UNAUTHORIZED", "Invalid API key.")

    auth_ws = next((w for w in workspaces if w.get("id") == auth_key.get("workspace_id")), None)
    if not auth_ws:
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="unauthorized", error_message="Workspace not found for API key.", input_payload=raw_payload)
        return _err("UNAUTHORIZED", "Invalid API key context.")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    auth_exp = _parse_dt(auth_key.get("expires_at"))
    if auth_key.get("status") != "active" or (auth_exp is not None and auth_exp <= now_dt):
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="api_key_revoked_or_expired", error_message="API key revoked or expired.", input_payload=raw_payload)
        return _err("UNAUTHORIZED", "API key revoked or expired.")

    # Authorization: must create only within same workspace
    if auth_key.get("workspace_id") != workspace_id:
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="unauthorized", error_message="Not permitted for this workspace.", input_payload=raw_payload)
        return _err("UNAUTHORIZED", "Not permitted to create API keys for this workspace.")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="not_found", error_message="Workspace not found.", input_payload=raw_payload)
        return _err("NOT_FOUND", "Workspace not found.")

    if ws.get("status") == "deleted":
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="conflict", error_message="Cannot create API key for deleted workspace.", input_payload=raw_payload)
        return _err("CONFLICT", "Cannot create API key for deleted workspace.")

    # unique(workspace_id, name)
    if any(k.get("workspace_id") == workspace_id and k.get("name") == name for k in api_keys):
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="conflict", error_message="API key name already exists in workspace.", input_payload=raw_payload)
        return _err("CONFLICT", "API key name already exists in this workspace.")

    # expires_at constraint: expires_at is null or expires_at > created_at
    now_iso = _now_iso()
    created_dt = _parse_dt(now_iso)
    if exp_dt is not None and created_dt is not None and exp_dt <= created_dt:
        _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="validation_error", error_message="expires_at must be after creation time.", input_payload=raw_payload)
        return _err("VALIDATION_ERROR", "expires_at must be after creation time.")

    # Create a new key secret and record (return secret once)
    secret = "gmap_live_" + secrets.token_urlsafe(32)
    prefix = secret[:8]
    if len(prefix) < 6:
        prefix = (prefix + "XXXXXX")[:6]

    # unique(prefix)
    if any(k.get("prefix") == prefix for k in api_keys):
        # re-roll a few times
        for _ in range(10):
            secret = "gmap_live_" + secrets.token_urlsafe(32)
            prefix = secret[:8]
            if not any(k.get("prefix") == prefix for k in api_keys):
                break
        if any(k.get("prefix") == prefix for k in api_keys):
            _record_request("failed", auth_key, workspace_id_r=workspace_id, error_code="conflict", error_message="Could not allocate unique key prefix.", input_payload=raw_payload)
            return _err("CONFLICT", "Could not allocate unique key prefix.")

    # Store only hash (simulate)
    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()

    new_id = "gmap_key_" + secrets.token_hex(12).upper()
    new_row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": name,
        "key_hash": key_hash,
        "prefix": prefix,
        "status": "active",
        "last_used_at": None,
        "expires_at": expires_at if expires_at is None else exp_dt.replace(microsecond=0).isoformat(),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    # Touch auth key last_used_at
    auth_key["last_used_at"] = now_iso
    auth_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    resp = {
        "api_key": {k: v for k, v in new_row.items() if k != "key_hash"},
        "key": secret
    }
    _record_request("succeeded", auth_key, workspace_id_r=workspace_id, response=resp, input_payload=raw_payload)
    return resp

def maps_update_api_key(api_key_id, target_api_key_id, name=None, expires_at=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "maps_update_api_key"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        h = hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24].upper()
        return f"{prefix}_{h}"

    # Validate inputs (tool schema)
    if not isinstance(api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id (expected pattern ^gmap_key_[0-9A-Z]{18,}$).")
    if not isinstance(target_api_key_id, str) or not re.match(r"^gmap_key_[0-9A-Z]{18,}$", target_api_key_id):
        return _err("VALIDATION_ERROR", "Invalid target_api_key_id (expected pattern ^gmap_key_[0-9A-Z]{18,}$).")
    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 120):
        return _err("VALIDATION_ERROR", "Invalid name (must be 1-120 characters) if provided.")
    if expires_at is not None and expires_at is not None:
        if expires_at is not None and not (isinstance(expires_at, str) or expires_at is None):
            return _err("VALIDATION_ERROR", "expires_at must be an ISO-8601 datetime string or null.")
    if status is not None and status not in ("active", "revoked"):
        return _err("VALIDATION_ERROR", "Invalid status (must be 'active' or 'revoked') if provided.")

    exp_dt = None
    if expires_at is None:
        exp_dt = None
    elif isinstance(expires_at, str):
        exp_dt = _parse_dt(expires_at)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "expires_at must be a valid ISO-8601 datetime string (e.g., 2027-02-01T00:00:00Z) or null.")

    # Load datastore
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    provider_connections = _load("provider_connections.json")
    maps_requests = _load("maps_requests.json")

    # Authenticate updater by api_key_id
    caller_key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not caller_key:
        return _err("UNAUTHORIZED", "API key not found.")
    caller_ws_id = caller_key.get("workspace_id")
    caller_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == caller_ws_id), None)
    if not caller_ws:
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace.")
    pcn = next((c for c in provider_connections if isinstance(c, dict) and c.get("workspace_id") == caller_ws_id and c.get("provider") == "google_maps_platform"), None)
    if not pcn:
        return _err("UNAUTHORIZED", "No provider connection available for this workspace.")
    provider_connection_id = pcn.get("id")

    # Find target key
    target = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == target_api_key_id), None)
    if not target:
        # record attempt is impossible without valid FK for api_key_id? We have caller api key; create request row under caller workspace.
        now = _utcnow()
        req_row = {
            "id": _new_id("gmap_req"),
            "workspace_id": caller_ws_id,
            "api_key_id": api_key_id,
            "provider_connection_id": provider_connection_id,
            "tool_name": tool_name,
            "status": "failed",
            "input": {
                "api_key_id": api_key_id,
                "target_api_key_id": target_api_key_id,
                "name": name,
                "expires_at": expires_at,
                "status": status,
            },
            "normalized_input": None,
            "cache_key": None,
            "provider_http_method": None,
            "provider_url": None,
            "provider_status_code": None,
            "provider_request_id": None,
            "response": None,
            "error_code": "not_found",
            "error_message": "Target API key not found.",
            "latency_ms": int(max(0, round((time.time() - t0) * 1000))),
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "deduped_from_request_id": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        maps_requests.append(req_row)
        _save("maps_requests.json", maps_requests)
        return _err("NOT_FOUND", "Target API key not found.", request_id=req_row["id"])

    # Authorization rule: must be in same workspace as caller (caller permitted key)
    if target.get("workspace_id") != caller_ws_id:
        now = _utcnow()
        req_row = {
            "id": _new_id("gmap_req"),
            "workspace_id": caller_ws_id,
            "api_key_id": api_key_id,
            "provider_connection_id": provider_connection_id,
            "tool_name": tool_name,
            "status": "failed",
            "input": {
                "api_key_id": api_key_id,
                "target_api_key_id": target_api_key_id,
                "name": name,
                "expires_at": expires_at,
                "status": status,
            },
            "normalized_input": None,
            "cache_key": None,
            "provider_http_method": None,
            "provider_url": None,
            "provider_status_code": None,
            "provider_request_id": None,
            "response": None,
            "error_code": "unauthorized",
            "error_message": "Caller API key is not permitted to update a key in another workspace.",
            "latency_ms": int(max(0, round((time.time() - t0) * 1000))),
            "billable_units": 0,
            "estimated_cost_usd": 0.0,
            "deduped_from_request_id": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        maps_requests.append(req_row)
        _save("maps_requests.json", maps_requests)
        return _err("UNAUTHORIZED", "Not permitted to update target API key.", request_id=req_row["id"])

    # Create maps_requests row for this invocation (business rule)
    now = _utcnow()
    req_row = {
        "id": _new_id("gmap_req"),
        "workspace_id": caller_ws_id,
        "api_key_id": api_key_id,
        "provider_connection_id": provider_connection_id,
        "tool_name": tool_name,
        "status": "running",
        "input": {
            "api_key_id": api_key_id,
            "target_api_key_id": target_api_key_id,
            "name": name,
            "expires_at": expires_at,
            "status": status,
        },
        "normalized_input": None,
        "cache_key": None,
        "provider_http_method": None,
        "provider_url": None,
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "billable_units": 0,
        "estimated_cost_usd": 0.0,
        "deduped_from_request_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Validate and enforce unique(workspace_id, name) if name changing
    new_name = None
    if name is not None:
        new_name = name.strip()
        if any(isinstance(k, dict) and k.get("workspace_id") == caller_ws_id and k.get("id") != target_api_key_id and k.get("name") == new_name for k in api_keys):
            req_row["status"] = "failed"
            req_row["error_code"] = "conflict"
            req_row["error_message"] = "API key name already exists in this workspace (unique(workspace_id, name))."
            req_row["updated_at"] = _iso(_utcnow())
            req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
            maps_requests.append(req_row)
            _save("maps_requests.json", maps_requests)
            return _err("CONFLICT", "API key name already exists in this workspace (unique(workspace_id, name)).", request_id=req_row["id"])

    # Validate expires_at constraint: null or > created_at
    if expires_at is not None:
        created_dt = _parse_dt(target.get("created_at")) if isinstance(target.get("created_at"), str) else None
        if exp_dt is not None and created_dt is not None and not (exp_dt > created_dt):
            req_row["status"] = "failed"
            req_row["error_code"] = "validation_error"
            req_row["error_message"] = "expires_at must be null or later than created_at."
            req_row["updated_at"] = _iso(_utcnow())
            req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
            maps_requests.append(req_row)
            _save("maps_requests.json", maps_requests)
            return _err("VALIDATION_ERROR", "expires_at must be null or later than created_at.", request_id=req_row["id"])

    # Enforce lifecycle transitions: only active -> revoked allowed; revoked immutable w.r.t status
    if status is not None:
        cur = target.get("status")
        if cur not in ("active", "revoked"):
            req_row["status"] = "failed"
            req_row["error_code"] = "validation_error"
            req_row["error_message"] = "Target API key has invalid stored status."
            req_row["updated_at"] = _iso(_utcnow())
            req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
            maps_requests.append(req_row)
            _save("maps_requests.json", maps_requests)
            return _err("VALIDATION_ERROR", "Target API key has invalid stored status.", request_id=req_row["id"])
        if cur == "revoked" and status == "active":
            req_row["status"] = "failed"
            req_row["error_code"] = "invalid_transition"
            req_row["error_message"] = "Invalid transition revoked -> active."
            req_row["updated_at"] = _iso(_utcnow())
            req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
            maps_requests.append(req_row)
            _save("maps_requests.json", maps_requests)
            return _err("INVALID_TRANSITION", "Invalid transition: revoked -> active.", request_id=req_row["id"])
        if cur == "active" and status == "active":
            # idempotent no-op for status; proceed for other fields
            pass
        if cur == "active" and status == "revoked":
            target["status"] = "revoked"

    # Apply mutations (must have effect or return NOT_FOUND; here target exists)
    changed = False
    if new_name is not None and target.get("name") != new_name:
        target["name"] = new_name
        changed = True
    if expires_at is not None:
        new_exp_str = _iso(exp_dt) if exp_dt is not None else None
        if target.get("expires_at") != new_exp_str:
            target["expires_at"] = new_exp_str
            changed = True
    if status is not None:
        if req_row["input"]["status"] == "revoked" and target.get("status") == "revoked":
            changed = True if True else changed  # status transition counts as change

    if not changed:
        # If nothing changed, still a valid call but must not claim mutation; reflect real APIs: return current object and succeed.
        # However business rule says every invocation creates a maps_requests row; complete it as succeeded.
        req_row["status"] = "succeeded"
        req_row["response"] = {"updated": False}
        req_row["updated_at"] = _iso(_utcnow())
        req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
        maps_requests.append(req_row)
        _save("maps_requests.json", maps_requests)
        return {"api_key": target, "updated": False}

    target["updated_at"] = _iso(_utcnow())
    _save("api_keys.json", api_keys)

    req_row["status"] = "succeeded"
    req_row["response"] = {"updated": True}
    req_row["updated_at"] = _iso(_utcnow())
    req_row["latency_ms"] = int(max(0, round((time.time() - t0) * 1000)))
    maps_requests.append(req_row)
    _save("maps_requests.json", maps_requests)

    return {"api_key": target, "updated": True}

def maps_whoami(api_key_id, workspace_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0280000" if __import__("os").path.isdir("./environment_mix/0280000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _start_of_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _start_of_month(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _rollup_id(workspace_id, period_type, period_start, tool_name):
        # deterministic id, but still matches "string" requirements; keep compact.
        import hashlib
        base = f"{workspace_id}|{period_type}|{_dt_iso(period_start)}|{tool_name}"
        h = hashlib.sha256(base.encode("utf-8")).hexdigest()[:24].upper()
        return f"gmap_roll_{h}"

    def _gen_req_id(existing_ids_set):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            s = "".join(secrets.choice(alphabet) for _ in range(22))
            rid = f"gmap_req_{s}"
            if rid not in existing_ids_set:
                return rid
        # fallback (should not happen)
        rid = f"gmap_req_{int(time.time()*1000)}"
        if rid in existing_ids_set:
            rid = f"{rid}_{len(existing_ids_set)+1}"
        return rid

    def _validate_and_resolve_key(api_key_id_value):
        if not isinstance(api_key_id_value, str):
            return None, _err("VALIDATION_ERROR", "api_key_id must be a string.")
        if not re.match(r"^gmap_key_[0-9A-Z]{18,}$", api_key_id_value):
            return None, _err("VALIDATION_ERROR", "api_key_id does not match required pattern.")
        keys = _load("api_keys.json")
        key = next((k for k in keys if k.get("id") == api_key_id_value), None)
        if not key:
            return None, _err("UNAUTHORIZED", "Invalid API key.")
        if key.get("status") != "active":
            return None, _err("UNAUTHORIZED", "API key revoked or inactive.")
        exp = _dt_parse(key.get("expires_at"))
        if exp is not None and not (exp > now):
            return None, _err("UNAUTHORIZED", "API key expired.")
        ws_id = key.get("workspace_id")
        if not isinstance(ws_id, str) or not ws_id:
            return None, _err("UNAUTHORIZED", "API key has no workspace binding.")
        return key, None

    def _resolve_workspace(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found.")
        return ws, None

    def _allowed_endpoints_for_workspace(ws_id):
        conns = _load("provider_connections.json")
        allowed = set()
        active_provider = False
        for c in conns:
            if c.get("workspace_id") != ws_id:
                continue
            if c.get("provider") != "google_maps_platform":
                continue
            if c.get("status") == "active":
                active_provider = True
                eps = c.get("allowed_endpoints")
                if isinstance(eps, list):
                    for e in eps:
                        if isinstance(e, str):
                            allowed.add(e)
        return sorted(allowed), active_provider

    def _sum_rollups(ws_id, period_type, period_start):
        rollups = _load("usage_rollups.json")
        rc = 0
        cost = 0.0
        bu = 0
        for r in rollups:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("period_type") != period_type:
                continue
            rs = _dt_parse(r.get("period_start"))
            if rs is None:
                continue
            if rs != period_start:
                continue
            if r.get("tool_name") != "*":
                continue
            try:
                rc += int(r.get("request_count", 0) or 0)
            except Exception:
                pass
            try:
                bu += int(r.get("billable_units", 0) or 0)
            except Exception:
                pass
            try:
                cost += float(r.get("estimated_cost_usd", 0) or 0.0)
            except Exception:
                pass
        if cost < 0:
            cost = 0.0
        if rc < 0:
            rc = 0
        if bu < 0:
            bu = 0
        return {"request_count": rc, "billable_units": bu, "estimated_cost_usd": cost}

    # ---- Input validation (including optional workspace_id) ----
    if not isinstance(api_key_id, str):
        # log attempt as failed request (tool invocation must create maps_requests row)
        # But need workspace_id/api_key_id/provider_connection_id foreign keys: cannot create without resolving.
        return _err("VALIDATION_ERROR", "api_key_id must be a string.")

    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            return _err("VALIDATION_ERROR", "workspace_id must be a string when provided.")
        if not re.match(r"^gmap_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id does not match required pattern.")

    # ---- Authenticate by api_key_id (explicit credential parameter) ----
    key, e = _validate_and_resolve_key(api_key_id)
    # If cannot authenticate, still should not create a maps_requests row because we cannot satisfy
    # maps_requests constraints (requires valid api_key_id fk). Real behavior states refuse invalid keys.
    if e:
        return e

    caller_ws_id = key.get("workspace_id")

    # workspace scope: must be accessible; with this schema, key binds to exactly one workspace.
    target_ws_id = workspace_id or caller_ws_id
    if target_ws_id != caller_ws_id:
        return _err("UNAUTHORIZED", "API key is not authorized for the requested workspace_id.")

    ws, e = _resolve_workspace(target_ws_id)
    if e:
        # If workspace missing, treat as unauthorized because key references a workspace that doesn't exist
        # in store; but schema says FK restrict, so it should exist.
        return _err("UNAUTHORIZED", "Workspace context is invalid for this API key.")

    # ---- Create maps_requests row for this tool invocation ----
    # Find an active provider connection for constraint satisfaction; if none, still record failed.
    conns = _load("provider_connections.json")
    provider_conn = None
    for c in conns:
        if c.get("workspace_id") == target_ws_id and c.get("provider") == "google_maps_platform":
            provider_conn = c
            # prefer active for serving
            if c.get("status") == "active":
                provider_conn = c
                break
    if provider_conn is None:
        # can't satisfy maps_requests FK provider_connection_id; treat as unauthorized because no viable combination
        return _err("UNAUTHORIZED", "No provider connection configured for this workspace.")

    reqs = _load("maps_requests.json")
    existing_ids = set(r.get("id") for r in reqs if isinstance(r.get("id"), str))
    req_id = _gen_req_id(existing_ids)

    # whoami doesn't incur provider cost; billable_units/cost set to 0
    req_row = {
        "id": req_id,
        "workspace_id": target_ws_id,
        "api_key_id": key.get("id"),
        "provider_connection_id": provider_conn.get("id"),
        "tool_name": "maps_geocode",  # INVALID: tool enum doesn't include maps_whoami
        "status": "failed",
        "input": {"api_key_id": api_key_id, "workspace_id": workspace_id},
        "normalized_input": None,
        "cache_key": None,
        "provider_http_method": None,
        "provider_url": None,
        "provider_status_code": None,
        "provider_request_id": None,
        "response": None,
        "error_code": "validation_error",
        "error_message": "Tool not billable/trackable in maps_requests enum.",
        "latency_ms": None,
        "billable_units": 0,
        "estimated_cost_usd": 0.0,
        "deduped_from_request_id": None,
        "created_at": _dt_iso(now),
        "updated_at": _dt_iso(now),
    }

    # The schema/business rules mandate maps_requests creation for "Every tool invocation (maps_geocode, ...)".
    # maps_whoami is not part of that list and is not in maps_requests.tool_name enum, so we must NOT write an
    # invalid row. We therefore record usage only through key last_used_at and return identity/quota.
    # (If we wrote it, we'd violate schema constraints and break reads.)

    # ---- Update key last_used_at ----
    keys = _load("api_keys.json")
    updated = False
    for k in keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = _dt_iso(now)
            k["updated_at"] = _dt_iso(now)
            updated = True
            break
    if updated:
        _save("api_keys.json", keys)

    # ---- Compute quota consumption from rollups ----
    day_start = _start_of_day(now)
    month_start = _start_of_month(now)
    daily = _sum_rollups(target_ws_id, "day", day_start)
    monthly = _sum_rollups(target_ws_id, "month", month_start)

    # Remaining (floor at 0)
    try:
        qdr = int(ws.get("quota_daily_requests"))
        qmr = int(ws.get("quota_monthly_requests"))
    except Exception:
        return _err("VALIDATION_ERROR", "Workspace quota fields are invalid.")
    try:
        qdc = float(ws.get("quota_daily_cost_usd"))
        qmc = float(ws.get("quota_monthly_cost_usd"))
    except Exception:
        return _err("VALIDATION_ERROR", "Workspace cost quota fields are invalid.")

    remaining_daily_requests = max(0, qdr - int(daily["request_count"]))
    remaining_monthly_requests = max(0, qmr - int(monthly["request_count"]))
    remaining_daily_cost = max(0.0, qdc - float(daily["estimated_cost_usd"]))
    remaining_monthly_cost = max(0.0, qmc - float(monthly["estimated_cost_usd"]))

    allowed_endpoints, has_active_provider = _allowed_endpoints_for_workspace(target_ws_id)

    # Workspace state included; whoami refuses suspended/deleted? Tool description says refuses invalid/revoked/expired keys.
    # We'll still return workspace status for visibility even if suspended, since key is valid; caller can see why calls fail.
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "identity": {
            "api_key": {
                "id": key.get("id"),
                "name": key.get("name"),
                "status": key.get("status"),
                "prefix": key.get("prefix"),
                "workspace_id": caller_ws_id,
                "expires_at": key.get("expires_at"),
                "last_used_at": _dt_iso(now),
            },
            "workspace": {
                "id": ws.get("id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "default_region": ws.get("default_region"),
                "default_language": ws.get("default_language"),
            },
        },
        "entitlements": {
            "provider": "google_maps_platform",
            "has_active_provider_connection": bool(has_active_provider),
            "allowed_endpoints": allowed_endpoints,
        },
        "quota": {
            "limits": {
                "daily_requests": qdr,
                "monthly_requests": qmr,
                "daily_cost_usd": qdc,
                "monthly_cost_usd": qmc,
            },
            "usage": {
                "daily": daily,
                "monthly": monthly,
            },
            "remaining": {
                "daily_requests": remaining_daily_requests,
                "monthly_requests": remaining_monthly_requests,
                "daily_cost_usd": remaining_daily_cost,
                "monthly_cost_usd": remaining_monthly_cost,
            },
            "period_starts": {
                "day": _dt_iso(day_start),
                "month": _dt_iso(month_start),
            },
        },
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": _dt_iso(now),
        },
    }
